import{_ as i,l as r,o as a,c,v as n,p as s,x as t,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"分布式锁与 fencing","description":"","frontmatter":{"title":"分布式锁与 fencing","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-lock-fencing.md","filePath":"cs/distributed-lock-fencing.md","lastUpdated":1789023840000}'),h={name:"cs/distributed-lock-fencing.md"};function f(u,e,k,_,g,b){const o=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=n('<h1 id="分布式锁与-fencing" tabindex="-1">分布式锁与 fencing <a class="header-anchor" href="#分布式锁与-fencing" aria-label="Permalink to &quot;分布式锁与 fencing&quot;">​</a></h1><div class="epigraph"><p>锁服务说「你持有」不够。持有者暂停后仍会写。必须把单调 fencing token 打进每一笔副作用，资源拒绝旧代。</p><footer>—— 据 Burrows, The Chubby Lock Service, OSDI 2006；Gray and Cheriton 租约；Ongaro 对 fencing 的讨论整理</footer></div><p>上一课<a href="/cs/leader-election-split-brain">脑裂</a>说至多一个有效主。缺口是<strong>锁的客户端会停很久再醒来</strong>：锁已过期发给别人，醒来的进程仍写共享存储。本课钉 fencing，不重写多数派选举。后课 Chubby/etcd 是把锁做成服务的例子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>错误模式：进程 A 得锁，GC 暂停，锁租约到期，B 得锁并写，A 醒来用旧连接写——后写覆盖。锁服务此时认为 A 已不是持有者，但存储不知道。缺口不是更短超时，而是<strong>资源验证代次</strong>。</p><p>Fencing token：锁每次授予单调递增整数。A 的 token=5，B 的 token=6。存储（或对象版本、或 HDFS 租约）拒绝 $\\lt $ 当前最大 token 的写。A 的迟到写失败。这把<a href="/cs/leases">租约</a>从「时间」换成「资源上的代次」。</p><p><span class="marginnote">没有存储配合，任何「分布式锁」都只是提示，不是互斥。ZooKeeper 食谱若只创节点不带 fencing，有经典坑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：acquire → 拿到 token → 所有写带 token。校验在资源侧，不在锁客户端侧。锁服务自己必须线性一致（RSM），否则两个 token 的「更大」没定义。</p>',9)),(a(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20LK%5B%22%E9%94%81%E6%9C%8D%E5%8A%A1%E5%8F%91%20token%22%5D%20--%3E%20CL%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A%20%20CL%20--%3E%7C%22%E5%86%99%20%2B%20token%22%7C%20ST%5B%22%E5%AD%98%E5%82%A8%22%5D%0A%20%20ST%20--%3E%20CMP%5B%22%E6%8B%92%E6%97%A7%20token%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>与互斥算法（Lamport bakery 等）：那些假定进程按协议走、不暂停后乱写外部。数据中心进程对外部有副作用，必须 fencing。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>etcd/ZK：用修订号、ZXID 当 token。Chubby：sequencer。对象存储：条件写 <code>If-Match</code> 版本。数据库：乐观版本列。缺条件写的 NFS 文件很难 fencing——不要用它当锁资源。</p><p>锁不是事务：持有期间崩溃，要靠租约到期。锁不是共识日志：它只互斥临界区，临界区里的状态复制仍要自己做。把「先拿锁再写两台数据库」当分布式事务，会在暂停窗口丢互斥——必须 token 进两库或改用 2PC/共识。</p><p>本课不把 Redis <code>SET NX</code> 当完整锁服务：默认无 fencing、过期与 GC 同构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写死锁检测图。不引入红锁的全部争论（点名：多独立 Redis 仍缺共享 fencing 资源则论证弱）。后课默认：锁 = 线性一致授予 + 资源侧 token。etcd/Chubby 下一课看服务形态。PoW 不是锁。</p><p>时间到期只回收锁。Token 才回收副作用权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>租约到期后旧持有者仍可能写；要 fencing token。</li><li>Token 必须由资源校验，锁客户端自报无效。</li><li>锁服务本身要线性一致，否则代次无全序。</li><li>出处：Burrows, OSDI 2006；租约文献。</li></ul>',10))])}const C=i(h,[["render",f]]);export{A as __pageData,C as default};
